function getExtraValues(){const v={};document.querySelectorAll('.extra-input').forEach(el=>{const lbl=el.closest('label');if(!lbl)return;const txt=(lbl.childNodes[0]?.textContent||'').trim();v[txt]=el.type==='checkbox'?el.checked:(el.type==='number'?(+el.value||0):el.value);});return v;}
function getExtraAdjustments(key,ex,area=1){
const p={},a={};let lab=1;if(key==='mantolama'){const sys=ex['Yalıtım sistemi']||'EPS',kal=ex['Levha kalınlığı']||'5 cm';let yf=1;if(sys==='Taş yünü')yf=1.35;else if(sys==='XPS')yf=1.25;if(kal==='8 cm'){yf*=1.40;lab=1.10;a['Yapıştırıcı']=1.15;a['Dübel']=1.1;}else if(kal==='10 cm'){yf*=1.70;lab=1.15;a['Yapıştırıcı']=1.3;a['Dübel']=1.2;}p['Yalıtım levhası']=yf;}else if(key==='seramik'){const eb=ex['Seramik ebatı']||'30×60 cm',dz=+ex['Derz genişliği']||3;if(eb==='60×60 cm')p['Seramik kaplama']=1.15;else if(eb==='60×120 cm')p['Seramik kaplama']=1.35;a['Derz dolgu']=Math.max(0.5,dz/3);}else if(key==='boya'){const kat=Math.max(1,+ex['Kat sayısı']||2),tip=ex['Boya tipi']||'Silikonlu',kf=kat/2;a['Astar']=kf;a['İç cephe boya']=kf;lab=kf;if(tip==='Silikat')p['İç cephe boya']=1.15;else if(tip==='Elastik')p['İç cephe boya']=1.25;}else if(key==='cati'){const egim=Math.min(60,Math.max(0,+ex['Çatı eğimi']||25)),kap=ex['Kaplama sistemi']||'Kiremit',ef=1/Math.cos(egim*Math.PI/180);a['Çatı kaplama']=ef;a['Su yalıtım örtüsü']=ef;a['Mahya elemanı']=ef;lab=ef;if(kap==='Metal panel')p['Çatı kaplama']=1.18;else if(kap==='Shingle')p['Çatı kaplama']=0.87;}else if(key==='parke'){const s=ex['Parke sınıfı']||'AC3';if(s==='AC4')p['Laminat parke']=1.20;else if(s==='Lamine')p['Laminat parke']=1.35;}else if(key==='alci'){const tip=ex['Uygulama tipi']||'Saten alçı',kat=Math.max(1,+ex['Kat sayısı']||2),kf=kat/2;a['Sıva harcı']=kf;a['Saten alçı']=kf;lab=kf;if(tip==='Makine sıvası'){p['Sıva harcı']=0.85;lab*=0.80;}else if(tip==='Kaba sıva'){p['Sıva harcı']=0.70;p['Saten alçı']=0.5;lab*=0.75;}}else if(key==='tugla'){const tip=ex['Tuğla tipi']||'13,5 cm',yuk=Math.max(1,+ex['Duvar yüksekliği']||2.8),yf=yuk/2.8;if(tip==='19 cm')p['Tuğla']=1.25;else if(tip==='Gazbeton'){p['Tuğla']=1.45;a['Tuğla']=0.6;}a['Duvar harcı']=yf;lab=yf;}else if(key==='beton'){const s=ex['Beton sınıfı']||'C25/30',dm=Math.max(50,+ex['Demir oranı kg/m³']||110);if(s==='C30/37')p['Hazır beton']=1.12;else if(s==='C35/45')p['Hazır beton']=1.22;a['Donatı çeliği']=dm/110;}else if(key==='elektrik'){const mh=ex['Mahal tipi']||'Daire',ht=Math.max(1,+ex['Hat uzunluğu']||4);if(mh==='Ofis'){p['Priz / anahtar seti']=1.15;lab=1.10;}else if(mh==='Dükkan'){p['Priz / anahtar seti']=0.90;lab=0.90;}a['Kablo ve boru']=ht/4;}else if(key==='tesisat'){const tu=ex['Tesisat türü']||'Temiz su',ca=ex['Çap']||'20 mm';if(tu==='Pis su')p['Atık su borusu']=1.10;else if(tu==='Karma'){p['PPRC boru ve fittings']=1.15;p['Atık su borusu']=1.15;lab=1.20;}let pp=p['PPRC boru ve fittings']||1;if(ca==='25 mm')p['PPRC boru ve fittings']=pp*1.15;else if(ca==='32 mm')p['PPRC boru ve fittings']=pp*1.30;}else if(key==='tadilat'){const b=Math.max(1,+ex['Banyo sayısı']||1),m=Math.max(1,+ex['Mutfak dolabı (mtül)']||5),k=Math.max(1,+ex['İç kapı sayısı']||7),q=ex['Malzeme Kalitesi']||'Standart',za=Math.max(10,+ex['Zemin net alanı (m²)']||100),ty=Math.max(2,+ex['Tavan yüksekliği (m)']||2.8);const duvarAlani=Math.sqrt(za)*4*ty,boyaAlani=duvarAlani+za,parkeAlani=za*0.8;a['Banyo yenileme (tüm kalemler)']=ex['Yenileme: Banyo']!==false?b:0;a['Mutfak yenileme (tüm kalemler)']=ex['Yenileme: Mutfak']!==false?m:0;a['Alçı, sıva ve iç cephe boya (duvar+tavan)']=ex['Yenileme: Boya & Alçı']!==false?boyaAlani:0;a['Laminat parke ve süpürgelik']=ex['Yenileme: Zemin Parke']!==false?parkeAlani:0;a['İç kapılar (kasa, kanat, montaj)']=ex['Yenileme: İç Kapılar']!==false?k:0;a['Elektrik tesisat altyapı ve montaj']=ex['Yenileme: Elektrik']!==false?za/100:0;a['Su tesisat altyapı ve montaj']=ex['Yenileme: Su Tesisatı']!==false?za/100:0;a['Kırım, söküm ve hafriyat']=za/100;a['Genel temizlik ve nakliye']=za/100;if(q==='Lüks'){p['Banyo yenileme (tüm kalemler)']=1.5;p['Mutfak yenileme (tüm kalemler)']=1.6;p['Laminat parke ve süpürgelik']=1.5;p['İç kapılar (kasa, kanat, montaj)']=1.8;p['Elektrik tesisat altyapı ve montaj']=1.3;p['Su tesisat altyapı ve montaj']=1.3;}else if(q==='Ekonomik'){p['Banyo yenileme (tüm kalemler)']=0.7;p['Mutfak yenileme (tüm kalemler)']=0.7;p['Laminat parke ve süpürgelik']=0.7;p['İç kapılar (kasa, kanat, montaj)']=0.7;p['Elektrik tesisat altyapı ve montaj']=0.8;}}else if(key==='banyo'){const ba=Math.max(2,area),kq=ex['Tasarım kalitesi']||'Standart';a['Seramik ve yapıştırıcı']=1/6;a['Vitrifiye ve bataryalar']=1/ba;a['Duşakabin ve tekne']=1/ba;a['Tesisat boru ve ekleme']=1/ba;a['Kırım, söküm ve moloz atımı']=1/ba;a['Banyo yenileme işçiliği']=1/ba;lab=1/6;if(kq==='Lüks'){p['Seramik ve yapıştırıcı']=1.6;p['Vitrifiye ve bataryalar']=2.5;p['Duşakabin ve tekne']=2.0;p['Tesisat boru ve ekleme']=1.3;lab*=1.4;}else if(kq==='Ekonomik'){p['Seramik ve yapıştırıcı']=0.7;p['Vitrifiye ve bataryalar']=0.6;p['Duşakabin ve tekne']=0.7;lab*=0.8;}}else if(key==='mutfak'){const mb=Math.max(2,area),kap=ex['Kapak türü']||'MDF Lam',tz=ex['Tezgah']||'Laminat';a['Mutfak dolabı gövde ve kapak']=1/5;a['Tezgah ve evye']=1/5;a['Tezgah arası seramik']=1/5;a['Kırım, tesisat ve hazırlık']=1/mb;a['Mutfak montaj ve işçiliği']=1/mb;lab=1/5;if(kap==='Lake')p['Mutfak dolabı gövde ve kapak']=1.8;else if(kap==='Akrilik')p['Mutfak dolabı gövde ve kapak']=1.4;if(tz==='Çimstone')p['Tezgah ve evye']=1.6;else if(tz==='Granit')p['Tezgah ve evye']=1.8;}else if(key==='daire_elektrik'){const da=Math.max(30,area),od=ex['Oda sayısı']||'3+1',mk=ex['Malzeme kalitesi']||'Standart',oc=od==='1+1'?0.6:od==='2+1'?0.8:od==='4+1'?1.2:od==='Dubleks'?1.8:1;a['Sigorta kutusu ve şalt']=oc/da;a['Kablo, boru ve buatlar']=1/100;a['Anahtar ve priz grubu']=(1/100)*oc*(mk==='Lüks'?1.2:1);a['Altyapı kırım ve işçilik']=1/da;lab=(1/100)*oc;if(mk==='Lüks'){p['Anahtar ve priz grubu']=1.8;p['Sigorta kutusu ve şalt']=1.5;}else if(mk==='Akıllı Ev'){p['Anahtar ve priz grubu']=3.5;p['Sigorta kutusu ve şalt']=3.0;p['Kablo, boru ve buatlar']=1.5;lab*=1.4;}}else if(key==='daire_tesisat'){const bs=Math.max(1,area),is=ex['Isıtma sistemi']||'Kombi & Radyatör';a['Temiz/pis su borulaması']=1/2;a['Kolektör ve vanalar']=1/2;a['Isıtma boru veya radyatör']=1/2;a['Tesisat kırım ve işçiliği']=1/bs;lab=1/2;if(is==='Yerden Isıtma'){p['Isıtma boru veya radyatör']=1.4;p['Kolektör ve vanalar']=1.5;lab*=1.3;}else if(is==='Sadece Altyapı'){a['Isıtma boru veya radyatör']=0.2;lab*=0.6;}}return{priceScale:p,amountScale:a,laborScale:lab};}
function calcRows(){ const d=tools[active], area=+$('#area').value||0, fire=1+(+$('#waste').value||0)/100, mode=$('#priceMode').value, extras=getExtraValues(), adj=getExtraAdjustments(active,extras); return d.items.map((it,i)=>{ const pa=adj.amountScale[it[0]]; if(pa===0) return null; const scale = pa===undefined?1:pa; let amount; if(it[4]==='İşçilik') amount=it[2]*area*adj.laborScale*scale; else if(it[1]==='götürü') amount=Math.max(1,it[2]<1?area*it[2]*scale:area/100*scale); else amount=it[2]*area*(/adet|tak�m|paket|g�t�r�/.test(it[1])?1:fire)*scale; if(/torba|adet|paket|takım/.test(it[1])) amount=Math.ceil(amount); const adjPrice=Math.round(it[3]*(adj.priceScale[it[0]]||1)); const price=mode==='quantity'?0:mode==='custom'?(+($(`#price-${i}`)?.value)||adjPrice):adjPrice; return {name:it[0],unit:it[1],coefficient:it[2],price,type:it[4],poz:it[5],amount,total:amount*price}; }).filter(Boolean); }

function workspace(tool='seramik', saved=null){ active=tools[tool]?tool:'seramik'; const d=tools[active]; const extra=d.inputs.map(([label,type,value],i)=>`<label>${label}${type==='select'?`<select class="extra-input" data-extra="${i}">${value.split('|').map(x=>`<option>${x}</option>`).join('')}</select>`:`<input class="extra-input" data-extra="${i}" type="${type}" value="${value}" ${type==='number'?'inputmode="decimal"':''}>`}</label>`).join(''); $('#calculator').innerHTML=`<div class="shell procalc"><div class="calcbar"><div><p class="eyebrow">— HESAPLAMA ÇALIŞMA ALANI</p><h2>${d.name}</h2><p><span class="status">2026 RESMİ POZ DÖNEMİ</span><span class="source">ÇŞİDB / Yüksek Fen Kurulu · ${d.poz}</span></p></div><div class="project-name"><label>Proje adı<input id="projectName" value="${saved?.name||`Yeni ${d.name} projesi`}"></label><button id="saveProject">Kaydet</button></div></div><div class="flow"><b class="active">1 <span>Bilgileri gir</span></b><b>2 <span>Fiyatları düzenle</span></b><b>3 <span>Sonucu incele</span></b><b>4 <span>Kaydet / paylaş</span></b></div><div class="workgrid"><section class="control"><h3>Ölçü ve kapsam</h3><div class="fieldgrid"><label>Net uygulama alanı<input id="area" type="number" inputmode="decimal" min="1" value="${saved?.area||100}"><small>${d.unit}</small></label><label>Fire oranı<input id="waste" type="number" inputmode="decimal" min="0" value="${saved?.waste??d.waste}"><small>%</small></label></div><div class="extra-grid">${extra}</div><label>Fiyat modu<select id="priceMode"><option value="official">2026 merkezi fiyatlar</option><option value="custom">Kendi fiyatlarım</option><option value="quantity">Sadece metraj</option></select></label><label class="vatcheck"><input id="vat" checked type="checkbox"> KDV dahil göster (%20)</label><p class="note">Fiyat kaynağı, işçilik, nakliye ve fire kalemleri ayrı hesaplanır. Kullanıcı fiyatı merkezi kaydı değiştirmez.</p><button class="btn navy" id="calculate">Sonucu güncelle →</button></section><section class="ledger"><div class="ledgerhead"><h3>Kalemler, pozlar ve birim fiyatlar</h3><button id="resetPrices">Varsayılan fiyatlar</button></div><div class="lineitems" id="lineitems"></div></section><aside class="summarycard"><small>YAKLAŞIK TOPLAM</small><strong id="grandTotal"></strong><p id="assumption"></p><hr><div><span>Malzeme</span><b id="materialsTotal"></b></div><div><span>İşçilik</span><b id="laborTotal"></b></div><div><span>Diğer gider</span><b id="otherTotal"></b></div><div><span>KDV</span><b id="vatTotal"></b></div><button id="offerFromCalc">PROKONT'tan teklif iste →</button></aside></div><div class="resultgrid"><section><div class="panelhead"><h3>Maliyet dağılımı</h3><span>Fiyat dönemi: 2026</span></div><div id="chart" class="costchart"></div></section><section><div class="panelhead"><h3>Fire dahil alışveriş listesi</h3><button id="csv">Excel/CSV indir</button></div><div id="shopping" class="shopping"></div></section></div><section class="project-history"><div class="panelhead"><h3>Kaydedilmiş hesaplar</h3><button id="clearHistory">Geçmişi temizle</button></div><div id="history"></div></section><div class="actionsrow"><button id="print">PDF olarak yazdır</button><button id="copy">Hesap özetini kopyala</button><button id="duplicate">Hesabı kopyala</button><small>Raporlar ekrandaki kalemler, fire, fiyat modu ve KDV ayarıyla üretilir.</small></div></div>`; bindWorkspace(); renderCalc(); analytics('tool_open',{tool:active}); }

function renderCalc(){ const d=tools[active], mode=$('#priceMode').value, _ex=getExtraValues(), _adj=getExtraAdjustments(active,_ex); const _cp={}; if(mode==='custom') d.items.forEach((_it,i)=>{const el=$(`#price-${i}`);if(el&&!el.disabled)_cp[i]=el.value;}); $('#lineitems').innerHTML=d.items.map((it,i)=>{const _ap=Math.round(it[3]*(_adj.priceScale[it[0]]||1));const _dp=mode==='custom'&&_cp[i]!==undefined?_cp[i]:_ap;return `<div class="line"><span><b>${it[0]}</b><small>POZ: ${it[5]} · ${it[1]} · ${it[4]}</small></span><label><input class="price" id="price-${i}" value="${_dp}" ${mode==='official'||mode==='quantity'?'disabled':''} inputmode="decimal"><small>TL/${it[1]}</small></label></div>`;}).join(''); const rows=calcRows(), groups=['Malzeme','İşçilik','Diğer'].map(type=>[type,rows.filter(x=>x.type===type).reduce((s,x)=>s+x.total,0)]), subtotal=groups.reduce((s,x)=>s+x[1],0), vat=$('#vat').checked?subtotal*.2:0, grand=subtotal+vat; $('#materialsTotal').textContent=money(groups[0][1]); $('#laborTotal').textContent=money(groups[1][1]); $('#otherTotal').textContent=money(groups[2][1]); $('#vatTotal').textContent=money(vat); $('#grandTotal').textContent=mode==='quantity'?'Fiyatsız metraj':money(grand); $('#assumption').textContent=`${$('#area').value} ${d.unit} net ölçü · %${$('#waste').value} fire · ${mode==='custom'?'kullanıcı fiyatları':'merkezi fiyat modu'}`; $('#chart').innerHTML=groups.map(([name,total])=>`<div><span>${name}</span><i><b style="width:${subtotal?total/subtotal*100:0}%"></b></i><strong>${mode==='quantity'?'—':money(total)}</strong></div>`).join(''); $('#shopping').innerHTML=rows.filter(x=>x.type==='Malzeme').map(x=>`<p><b>${x.name}<small>POZ ${x.poz}</small></b><span>${qty(x.amount)} ${x.unit}</span></p>`).join(''); $$('.price').forEach(x=>x.oninput=renderCalc); }

function readProject(){ const rows=calcRows(), mode=$('#priceMode').value; return {id:crypto.randomUUID?.()||Date.now().toString(),name:$('#projectName').value,tool:active,area:$('#area').value,waste:$('#waste').value,mode,rows,createdAt:new Date().toISOString()}; }
function projects(){ return JSON.parse(localStorage.getItem('prokontProjects')||'[]'); }
function renderHistory(){ const host=$('#history'); const list=projects(); host.innerHTML=list.length?list.slice(0,5).map(x=>`<button class="history-item" data-project="${x.id}"><b>${x.name}</b><span>${tools[x.tool].name} · ${x.area} ${tools[x.tool].unit} · ${new Date(x.createdAt).toLocaleDateString('tr-TR')}</span></button>`).join(''):'<p class="empty-state">Henüz kaydedilmiş hesap yok. Hesabınızı istediğiniz zaman buradan açmak için kaydedin.</p>'; $$('.history-item').forEach(b=>b.onclick=()=>{const x=projects().find(p=>p.id===b.dataset.project); if(x) workspace(x.tool,x);}); }
function bindWorkspace(){ $('#calculate').onclick=()=>{renderCalc();analytics('calculation_complete',{tool:active});}; $('#priceMode').onchange=()=>{renderCalc();analytics('price_mode',{mode:$('#priceMode').value,tool:active});}; ['area','waste','vat'].forEach(id=>$('#'+id).oninput=renderCalc); $$('.extra-input').forEach(el=>{el.oninput=renderCalc;el.onchange=renderCalc;}); $('#resetPrices').onclick=renderCalc; $('#saveProject').onclick=()=>{const list=projects(); list.unshift(readProject()); localStorage.setItem('prokontProjects',JSON.stringify(list.slice(0,30))); renderHistory(); toast('Hesap tarayıcınıza kaydedildi.'); analytics('project_save',{tool:active});}; $('#clearHistory').onclick=()=>{localStorage.removeItem('prokontProjects');renderHistory();toast('Kaydedilmiş hesaplar temizlendi.');}; $('#csv').onclick=()=>downloadCsv(calcRows()); $('#print').onclick=()=>{analytics('report_pdf',{tool:active});window.print();}; $('#copy').onclick=()=>navigator.clipboard.writeText(`${$('#projectName').value}: ${$('#grandTotal').textContent}`).then(()=>toast('Hesap özeti kopyalandı.')); $('#duplicate').onclick=()=>{const n=$('#projectName');n.value+=' (Kopya)';toast('Kopya proje hazır.');}; $('#offerFromCalc').onclick=()=>openOffer(readProject()); renderHistory(); }
function downloadCsv(rows){ const header='Poz No;Kalem;Birim;Miktar;Birim Fiyat;Tutar\n'; const content=header+rows.map(x=>`${x.poz};${x.name};${x.unit};${x.amount};${x.price};${x.total}`).join('\n'); const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));a.download=`${$('#projectName').value.replaceAll(' ','-')||'prokont-hesap'}.csv`;a.click();URL.revokeObjectURL(a.href);analytics('report_excel',{tool:active}); }



function enhanceCompare(){ const box=$('#comparisonContent'); if(!box)return; const data={insulation:[['EPS','680','Isı yalıtımı','Orta','Ekonomik cephe'],['Taş yünü','920','Isı + ses yalıtımı','Yüksek','Yangın öncelikli cephe'],['XPS','850','Neme dayanım','Yüksek','Toprak altı / nemli alan']],flooring:[['Laminat','720','Aşınma direnci','Orta','Konut'],['Lamine','1.650','Doğal ahşap','Orta','Prestij alanlar'],['Vinil','890','Suya dayanım','Yüksek','Yoğun kullanım']],paint:[['Silikonlu','175','Silinebilirlik','Orta','İç cephe'],['Silikat','250','Nefes alma','Yüksek','Mineral yüzey'],['Elastik','310','Çatlak köprüleme','Yüksek','Dış cephe']],roof:[['Kiremit','1.250','Uzun ömür','Yüksek','Eğimli çatı'],['Metal panel','1.480','Hızlı montaj','Orta','Hafif çatı'],['Shingle','1.090','Esnek uygulama','Orta','Küçük eğimli çatı']]}; function draw(key='insulation'){const area=+$('#compareArea')?.value||100, rows=data[key];box.innerHTML=`<div class="compare-controls"><label>Proje alanı <input id="compareArea" type="number" value="${area}" inputmode="decimal"> m²</label><span>2026 merkezi maliyet karşılaştırması</span></div><div class="compare-table"><div class="compare-row compare-label"><span>Seçenek</span><span>Birim maliyet</span><span>Toplam maliyet</span><span>Teknik özellik</span><span>Uygun kullanım</span></div>${rows.map((r,i)=>`<button class="compare-row ${i===0?'recommended':''}" data-tool="${key==='insulation'?'mantolama':key==='flooring'?'parke':key==='paint'?'boya':'cati'}"><span><b>${r[0]}</b>${i===0?'<small>Fiyat / performans</small>':''}</span><span>${r[1]} TL/m²</span><span>${money(+r[1]*area)}</span><span>${r[2]} · yangın: ${r[3]}</span><span>${r[4]} <i>→</i></span></button>`).join('')}</div><p class="compare-note">Teknik değerler nihai karar için üretici teknik föyü ve ilgili standartla doğrulanmalıdır.</p>`; $('#compareArea').oninput=()=>draw(key); $$('.compare-row[data-tool]').forEach(x=>x.onclick=()=>{workspace(x.dataset.tool);$('#calculator').scrollIntoView({behavior:'smooth'});}); } $$('.tabs [data-kind]').forEach(b=>b.onclick=()=>{$$('.tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');draw(b.dataset.kind);analytics('comparison_open',{kind:b.dataset.kind});});draw(); }

function openOffer(project){ const dialog=$('#dialog'); dialog.showModal(); const text=dialog.querySelector('textarea'); const fields=dialog.querySelector('form'); if(!dialog.querySelector('#city')){fields.insertAdjacentHTML('afterbegin','<label>İl / İlçe<input id="city" required placeholder="Örn. Kayseri / Melikgazi"></label><label>Fotoğraf veya proje dosyası<input id="attachment" type="file" accept="image/*,.pdf"></label>');} if(project)text.value=`${project.name} | ${tools[project.tool].name} | ${project.area} ${tools[project.tool].unit} | ${project.mode}`; }

function setupSearch(){ const aliases={seramik:['seramik','fayans','derz'],mantolama:['mantolama','eps','taş yünü','xps'],boya:['boya','litre'],tadilat:['tadilat','ev','banyo','mutfak'],cati:['çatı'],parke:['parke'],alci:['alçı','sıva'],tugla:['tuğla','gazbeton','duvar'],beton:['beton','demir'],elektrik:['elektrik','priz'],tesisat:['tesisat','boru','su']}; const search=()=>{const searchEl = $('#search'); if(!searchEl) return; const q=searchEl.value.toLocaleLowerCase('tr').trim(); const res = $('#results'); if(!res) return; if(!q){res.classList.remove('show');return;} const matches=Object.entries(aliases).filter(([,a])=>a.some(x=>q.includes(x))).map(([k])=>k); const picked=matches.length?matches:['seramik','tadilat']; res.innerHTML=`<div class="result-group"><small>HESAPLAMA ARAÇLARI</small>${picked.slice(0,3).map(k=>`<button data-found="${k}"><b>${tools[k].name}</b><span>${tools[k].category} · ${tools[k].poz}</span></button>`).join('')}</div><div class="result-group"><small>TEKNİK BİLGİLER</small><button data-anchor="knowledge"><b>${q} hakkında teknik rehber</b><span>Bilgi Merkezi</span></button></div><div class="result-group"><small>PROKONT HİZMETLERİ</small><button data-anchor="offer"><b>Profesyonel keşif ve teklif desteği</b><span>Hesabınızı ekleyin</span></button></div>`;res.classList.add('show');$$('[data-found]').forEach(b=>b.onclick=()=>{workspace(b.dataset.found);res.classList.remove('show');$('#calculator')?.scrollIntoView({behavior:'smooth'});analytics('search_open',{query:q,tool:b.dataset.found});});$$('[data-anchor]').forEach(b=>b.onclick=()=>$('#'+b.dataset.anchor)?.scrollIntoView({behavior:'smooth'}));};
if($('#find')) $('#find').onclick=search;
if($('#search')) $('#search').oninput=search;
if($('#searchToggle')) $('#searchToggle').onclick=()=>{if($('#search')) $('#search').focus(); if($('.finder')) $('.finder').scrollIntoView({behavior:'smooth'});};
$$('.finder p button').forEach(b=>b.onclick=()=>{if($('#search')) $('#search').value=b.textContent;search();}); }

function addMegaMenu(){ const link=$('nav a[href="#tools"]'); if(!link) return; const wrap=document.createElement('div'); wrap.className='calc-mega'; wrap.innerHTML=`<div><b>Hesaplama Merkezi</b><small>İşinize göre aracı seçin.</small></div>${Object.entries(tools).map(([key,t])=>`<button data-mega="${key}"><span>${t.category}</span>${t.name}<i>→</i></button>`).join('')}`; link.parentElement.append(wrap); const open=()=>wrap.classList.add('open'), close=()=>wrap.classList.remove('open'); link.onmouseenter=open; wrap.onmouseenter=open; link.parentElement.onmouseleave=close; link.onclick=e=>{e.preventDefault();wrap.classList.toggle('open');}; $$('[data-mega]').forEach(b=>b.onclick=()=>{workspace(b.dataset.mega);$('#calculator')?.scrollIntoView({behavior:'smooth'});close();}); }
function init(){ const external=JSON.parse(localStorage.getItem('prokontExternalTool')||'null'); if(external?.name){tools.harici={name:external.name+' Hesabı',category:external.category||'Özel İmalat',poz:'Özel imalat maliyet modeli',unit:external.unit||'m²',waste:5,inputs:[['Uygulama türü','select',`${external.name}|Standart uygulama|Premium uygulama`],['Proje notu','text','Özel hesaplama']],items:[[`${external.name} malzemesi`,external.unit||'m²',1,+external.material||1000,'Malzeme','-'],[`${external.name} işçiliği`,external.unit||'m²',1,+external.labor||350,'İşçilik','-'],['Nakliye / sarf','götürü',1,(+external.material||1000)*.05,'Diğer','-']]};localStorage.removeItem('prokontExternalTool');} renderToolFilters(); addMegaMenu(); $$('.tool-tile[data-tool], [data-tool]').forEach(b=>b.onclick=e=>{e.preventDefault();workspace(b.dataset.tool);$('#calculator')?.scrollIntoView({behavior:'smooth',block:'start'});}); setupSearch();  enhanceCompare(); 


if($('#offerBtn')) $('#offerBtn').onclick=()=>openOffer(); 
if($('#close')) $('#close').onclick=()=>$('#dialog')?.close();
const modalDlg = $('#dialog');
if(modalDlg) {
  modalDlg.addEventListener('click', (e) => {
    const rect = modalDlg.getBoundingClientRect();
    if (e.clientX < rect.left || e.clientX > rect.right || e.clientY < rect.top || e.clientY > rect.bottom) {
      modalDlg.close();
    }
  });
}
const attInput = $('#attachment');
if(attInput) {
  attInput.onchange = () => {
    if(attInput.files && attInput.files[0]) {
      const f = attInput.files[0];
      const t = $('#fileTitle'); if(t) t.textContent = f.name;
      const h = $('#fileHint'); if(h) h.textContent = (f.size / 1024 / 1024).toFixed(2) + ' MB · Dosya seçildi';
    }
  };
} 
if($('#offerForm')) $('#offerForm').onsubmit = async e => {
  e.preventDefault();
  const submitBtn = $('#offerForm button[type="submit"]');
  const originalBtnHTML = submitBtn ? submitBtn.innerHTML : '';
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<span>Belge Yükleniyor...</span>';
  }

  const name = ($('#nameInput')?.value || '').trim();
  const phone = ($('#phoneInput')?.value || '').trim();
  const city = ($('#city')?.value || '').trim();
  const notes = ($('#offerNotes')?.value || '').trim();
  const attachment = $('#attachment')?.files?.[0];

  let fileUrl = '';
  if (attachment) {
    try {
      const base64Data = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(attachment);
      });
      const uploadRes = await fetch('/api/upload', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: attachment.name, data: base64Data })
      });
      if (uploadRes.ok) {
        const fileJson = await uploadRes.json();
        fileUrl = location.origin + '/' + fileJson.url;
      }
    } catch (err) {
      console.warn('Dosya sunucuya yüklenemedi:', err);
    }
  }

  let msg = '🏗️ *PROKONT - Yeni Teklif Talebi*\n\n';
  msg += '👤 *İsim:* ' + (name || 'Belirtilmedi') + '\n';
  msg += '📞 *Telefon:* ' + (phone || 'Belirtilmedi') + '\n';
  msg += '📍 *Konum:* ' + (city || 'Belirtilmedi') + '\n';
  if (notes) {
    msg += '📝 *Proje Notu:*\n' + notes + '\n';
  }
  if (fileUrl) {
    // WhatsApp'ın linki tam tanıması için etrafında boş satır olmalıdır
    msg += '\n📎 *Yüklenen Proje Dosyası Linki:*\n\n' + fileUrl + '\n\n';
  } else if (attachment) {
    msg += '\n📎 *Seçilen Dosya:* ' + attachment.name + '\n';
  }

  const testPhone = '905447414393';
  const waUrl = 'https://wa.me/' + testPhone + '?text=' + encodeURIComponent(msg);

  window.open(waUrl, '_blank');
  $('#dialog')?.close();
  if (submitBtn) {
    submitBtn.disabled = false;
    submitBtn.innerHTML = originalBtnHTML;
  }
  toast(fileUrl ? 'Belgeniz yüklendi ve WhatsApp aktarıldı!' : 'Teklif talebiniz WhatsApp\'a aktarılıyor...');
  analytics('offer_request_whatsapp', { testPhone: testPhone, hasFile: !!fileUrl });
};

const requested=external?.name?'harici':localStorage.getItem('prokontRequestedTool'); if(requested&&tools[requested]){localStorage.removeItem('prokontRequestedTool');workspace(requested);setTimeout(()=>$('#calculator')?.scrollIntoView({behavior:'smooth',block:'start'}),80);}else{ if($('#calculator')) workspace(); } }
init();



